function shamsiParts(iso){var m=String(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;var g={y:Number(m[1]),m:Number(m[2]),d:Number(m[3])},j=g2j(g.y,g.m,g.d),dt=new Date(g.y,g.m-1,g.d,12,0,0);return{year:j.jy,month:j.jm,day:j.jd,weekday:dt.getDay()};}
function shamsiDate(iso,withWeekday){var p=shamsiParts(iso);if(!p)return String(iso||'');var months=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],days=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];return (withWeekday?days[p.weekday]+' ':'')+faNum(p.day)+' '+months[p.month-1]+' '+faNum(p.year);}
