function api(method,path,body,cb){
  var epoch=state.authEpoch;
  return API.request(method,path,body,function(err,data,status){
    if(epoch!==state.authEpoch)return;
    if(!err)state.lastSyncAt=Date.now();
    if(cb)cb(err,data,status);
  });
}
function queueKey(){return 'moshaver_queue:'+(state.me&&state.me.id?state.me.id:'anonymous');}
