function showFocus(t){if(!t)return;el('focusSubject').textContent=t.subject||typeLabels[t.type]||'مطالعه';el('focusTitle').textContent=t.title||'';var g='';if(t.pages)g+='<span>صفحه '+esc(t.pages)+'</span>';if(t.testCount)g+='<span>'+faNum(t.testCount)+' تست</span>';g+='<span>'+esc(t.start)+' تا '+esc(t.end)+'</span>';el('focusGoal').innerHTML=g;el('focusMode').className='focus-mode';}
