function showQuizSubmitReview(){var c=quizCounts();saveQuizDraft();el('quizBody').innerHTML='<div class="quiz-submit-review"><span class="eyebrow">بررسی پیش از ثبت</span><h3>پاسخ‌ها آماده ثبت هستند؟</h3><p>بعد از ثبت نهایی، پاسخ این تلاش قابل تغییر نیست.</p><div class="quiz-submit-summary"><span><strong>'+faNum(c.answered)+'</strong><small>پاسخ‌داده</small></span><span><strong>'+faNum(c.blank)+'</strong><small>بدون پاسخ</small></span><span><strong>'+faNum(c.flagged)+'</strong><small>علامت‌دار</small></span></div>'+(c.blank?'<p class="exam-warning">هنوز '+faNum(c.blank)+' سؤال بدون پاسخ داری. می‌توانی برگردی و آن‌ها را کامل کنی.</p>':'<p class="exam-pending">همه سؤال‌ها پاسخ داده شده‌اند.</p>')+'<div class="quiz-result-actions"><button id="quizReturnToQuestions" class="btn soft full">بازگشت به سؤال‌ها</button><button id="quizConfirmSubmit" class="btn primary full">ثبت نهایی آزمون</button></div></div>';el('quizReturnToQuestions').onclick=renderQuiz;el('quizConfirmSubmit').onclick=function(){finishQuiz(false);};updateQuizTimer();}
