function chatBodyHtml(m){if(m.deletedAt)return '<p class="deleted-message">پیام حذف شده</p>';if(m.type&&m.type!=='text'&&m.type!=='system')return chatSnapshotHtml(m);if(m.type==='system')return '<p class="system-message">'+esc(m.text)+'</p>';return '<div class="chat-markdown">'+window.MoshaverChatMarkdown.render(m.text||'')+'</div>';}
