function bindGroupInfoActions(){var d=state.chatGroupDetail,candidateSeq=0,candidateTimer=null;if(el('candidateSearch'))el('candidateSearch').oninput=function(){var term=this.value.trim(),seq=++candidateSeq;clearTimeout(candidateTimer);if(term.length<1){el('candidateResults').innerHTML='';return;}candidateTimer=setTimeout(function(){api('GET','/chat/groups/'+encodeURIComponent(d.id)+'/candidates?limit=15&search='+encodeURIComponent(term),null,function(err,rows){if(err||seq!==candidateSeq)return;el('candidateResults').innerHTML=rows.map(function(x){return '<button data-add-member="'+esc(x.id)+'">＋ '+esc(x.name)+' <small>@'+esc(x.username)+'</small></button>';}).join('');qa('[data-add-member]',el('candidateResults')).forEach(function(b){b.onclick=function(){api('POST','/chat/groups/'+encodeURIComponent(d.id)+'/members',{userId:this.getAttribute('data-add-member')},function(er){if(er)return toast(er.message,'error');openGroupInfo();});};});});},250);};qa('[data-remove-member]').forEach(function(b){b.onclick=function(){if(confirm('عضو از گروه حذف شود؟'))api('DELETE','/chat/groups/'+encodeURIComponent(d.id)+'/members/'+encodeURIComponent(this.getAttribute('data-remove-member')),null,function(e){if(e)return toast(e.message,'error');openGroupInfo();});};});qa('[data-role-member]').forEach(function(b){b.onclick=function(){api('PATCH','/chat/groups/'+encodeURIComponent(d.id)+'/members/'+encodeURIComponent(this.getAttribute('data-role-member')),{role:this.getAttribute('data-role')},function(e){if(e)return toast(e.message,'error');openGroupInfo();});};});if(el('muteGroup'))el('muteGroup').onclick=function(){api('PATCH','/chat/conversations/'+encodeURIComponent(d.id)+'/mute',{muted:!d.muted},function(e){if(e)return toast(e.message,'error');openGroupInfo();});};if(el('leaveGroup'))el('leaveGroup').onclick=function(){if(confirm('گروه را ترک می‌کنید؟'))api('POST','/chat/groups/'+encodeURIComponent(d.id)+'/leave',{},function(e){if(e)return toast(e.message,'error');closeModals();state.chatConversation=null;loadConversationList();});};if(el('editGroupPermissions'))el('editGroupPermissions').onclick=openPermissionEditor;}
