function openShareMenu(){if(!state.chatConversation||state.chatConversation.type!=='group')return toast('اشتراک وضعیت فقط در گروه انجام می‌شود.');el('examModalBody').innerHTML='<div class="share-picker"><h3>چه چیزی را به اشتراک می‌گذاری؟</h3><p>فقط مواردی که انتخاب می‌کنی به‌صورت یک تصویر ثابت ارسال می‌شوند.</p><label><input type="checkbox" data-share-field="studyMinutes" checked> زمان مطالعه امروز</label><label><input type="checkbox" data-share-field="planProgress" checked> اجرای برنامه</label><label><input type="checkbox" data-share-field="testCount"> تعداد تست</label><label><input type="checkbox" data-share-field="reviews"> مرورهای امروز</label><button id="shareStudyState" class="btn primary full">اشتراک وضعیت امروز</button><button id="shareStudyTime" class="btn soft full">اشتراک زمان هفت روز</button><button id="shareCurrentActivity" class="btn soft full">اشتراک فعالیت فعلی</button></div>';openModal('examModal');el('shareStudyState').onclick=function(){var fields=[];qa('[data-share-field]').forEach(function(x){if(x.checked)fields.push(x.getAttribute('data-share-field'));});sendSnapshot('study-state',{fields:fields});};el('shareStudyTime').onclick=function(){sendSnapshot('study-time',{days:7});};el('shareCurrentActivity').onclick=function(){sendSnapshot('current-activity',{});};}
function sendSnapshot(kind,body){var conversationId=state.chatConversation&&state.chatConversation.id;if(!conversationId)return;api('POST','/chat/conversations/'+encodeURIComponent(conversationId)+'/share/'+kind,body,function(err,item){if(err)return toast(err.message,'error');closeModals();if(!state.chatConversation||state.chatConversation.id!==conversationId)return;mergeChatMessage(item);renderChat(true);});}
function disconnectEvents(){if(state.eventSource){try{state.eventSource.close();}catch(e){}state.eventSource=null;}if(state.chatPoll){clearInterval(state.chatPoll);state.chatPoll=null;}}
function conversationById(id){for(var i=0;i<state.chatConversations.length;i++)if(state.chatConversations[i].id===id)return state.chatConversations[i];return null;}
function applyStudentMessageEvent(type,data){if(!data)return false;var m=data.id?findChatMessage(data.id):data.messageId?findChatMessage(data.messageId):null;if(type==='chat.message.edited'&&m){m.text=data.text;m.editedAt=data.editedAt;renderChat(false);return true;}if(type==='chat.message.deleted'&&m){m.deletedAt=data.deletedAt;m.text='';renderChat(false);return true;}if(type==='chat.reaction.updated'&&m){m.reactions=data.reactions||[];renderChat(false);return true;}return false;}
function realtimeEvent(type,data){if(type==='chat.message.created'){var c=data&&conversationById(data.conversationId),current=data&&state.chatConversation&&data.conversationId===state.chatConversation.id;if(current){if(binaryInsertUnique(state.chatMessages,data,compareChatMessage))renderChat(false);if(chatActive())markChatRead();}else{if(c){c.unread=Number(c.unread||0)+1;c.lastMessage={id:data.id,text:data.text,type:data.type,createdAt:data.createdAt,senderName:data.senderName};state.chatConversations.splice(state.chatConversations.indexOf(c),1);state.chatConversations.unshift(c);renderStudentConversationList();}setChatBadge(state.chatUnread+1);}if(!chatActive()&&!(c&&c.muted))toast('پیام جدید از مشاور');return;}if(type==='chat.message.edited'||type==='chat.message.deleted'||type==='chat.reaction.updated'){applyStudentMessageEvent(type,data);return;}if(type==='chat.conversation.created'||type==='chat.conversation.updated'||type==='chat.member.added'||type==='chat.member.removed'||type==='chat.member.updated'){loadConversationList();return;}if(type==='chat.mention.created'){var mc=data&&conversationById(data.conversationId);if(!(mc&&mc.muted))toast((data&&data.senderName?data.senderName+' ':'')+'شما را در گفتگو نام برد');return;}if(type==='chat.messages.read'){if(chatActive())loadChat(false);return;}if(type==='plan.published'||type==='plan.updated'){toast('برنامه توسط مشاور به‌روزرسانی شد');loadDashboard();if(el('view-schedule').classList.contains('active'))loadSchedule(state.scheduleDate||isoToday());return;}if(type==='exam.updated'||type==='exam.retry_reviewed'){toast(type==='exam.retry_reviewed'?'وضعیت درخواست آزمون به‌روزرسانی شد':'آزمون توسط مشاور به‌روزرسانی شد');if(el('view-exams').classList.contains('active'))loadExams();loadDashboard();return;}if(type==='advisor.comment.created'){toast('پیام جدید مشاور برای یکی از فعالیت‌ها');return;}if(type==='notification.created'){if(state.dashboard)state.dashboard.unreadNotifications=Number(state.dashboard.unreadNotifications||0)+1;var b=el('notificationBadge'),n=state.dashboard?Number(state.dashboard.unreadNotifications||0):1;b.textContent=faNum(n);b.className='badge';if(global.NotificationSync)global.NotificationSync.sync(true);if(!data||data.type!=='message')toast(data&&data.title?data.title:'اعلان جدید');return;}if(type==='review.created')return loadReviews();if(type==='learning.updated'){toast('برنامه مرور به‌روزرسانی شد');loadLearning();loadDashboard();return;}}
function connectEvents(){disconnectEvents();state.eventSource=API.openEvents(realtimeEvent,function(st){var p=el('advisorPresence');if(!p)return;if(st==='open'){p.textContent='● ارتباط زنده';p.className='chat-presence online';}else{p.textContent='○ در حال اتصال';p.className='chat-presence reconnecting';}});if(!state.eventSource)state.chatPoll=setInterval(function(){if(chatActive())loadChat(false);},20000);}

